-- Gathering 4 in the storybook voice (Fake Guru, 16 Oct), generated by scripts/gen-gathering-sql.ts 4 from the updated episode file.
-- Gathering 4, generated by scripts/gen-gathering-sql.ts. Do not edit by hand.
insert into public.gathering_scripts (series_id, season_number, week, data) values
('dark-moon', 1, 4, '{"meta":{"dc":10,"ueDc":8,"def":25,"atk":18,"reward":740,"enemy":"The Faithful","condition":"Knee-deep: roll a 1, 2 or 3 on a strike and you lose your next strike. So does he.","ueAttr":"Craft","ueTitle":"THE WATER-GATE","barWay":"The Pin","barRisk":"His Breath"},"steps":[{"t":"tonight","text":"Tonight: the Gathering. After the oars, in the boat you took from them. Tonight calls on Craft.","section":""},{"t":"section","title":"Arrival and the Approach","section":"Arrival and the Approach"},{"t":"say","text":"Oars, in the dark, pulling away toward the drowned village. You are already in the boat you took from them, and already rowing. The water is so black that the blades vanish into it at every stroke.","section":"Arrival and the Approach"},{"t":"pick","vote":true,"question":"HOW DO YOU FOLLOW?","options":[{"label":"OPEN WATER","desc":"quick, and nothing in it to steer by but the sound."},{"label":"THE DROWNED ROOFS","desc":"a road you can feel with an oar. Slower, and every roof looks like the last."}],"section":"Arrival and the Approach","mode":"vote"},{"t":"approach","title":"THE BLACK LAKE","ways":[{"by":"Across open water","attr":"Aim","verb":"hold a line on a sound"},{"by":"Along the roofs","attr":"Might","verb":"row hard, and keep the oars quiet"}],"reward":"+500g · **and the party strikes first**","fail":"you lose the sound twice, and **they strike first**","section":"Arrival and the Approach"},{"t":"say","text":"You never lose them. The knock of their oars stays just ahead of you the whole way.","cond":{"on":"approach","pass":true},"section":"Arrival and the Approach"},{"t":"say","text":"Twice the knock of their oars is swallowed by the dark. Twice you sit on the black water with nothing but your own breath, until it comes again.","cond":{"on":"approach","pass":false},"section":"Arrival and the Approach"},{"t":"say","text":"Nobody speaks. The lake is black, the sky is black, and the only thing to steer by is that faint, steady knock of wood on water somewhere ahead. Then the drowned church comes up out of the dark beside you, and the oars stop.\n\nIt stands at the edge of the deep water, its roof long gone. Its flooded stair leads down under the streets into an undercroft, where the lake has come in through the old stone and stands knee-deep, black and still, at every chamber door.\n\nYou go in with the cold climbing your legs and your lamps held high, and for the first time since Meira''s list found you, you are close enough to hear it happening: a child''s cry cut short, and the slap of feet running away through water.","section":"Arrival and the Approach"},{"t":"section","title":"The Battle","section":"The Battle"},{"t":"say","text":"They are waiting in the water. {N} of them, robed, about a stone table, with the lamplight shaking on the black water at their knees. The cold has your legs to the bone already. They come at you through it, slow and certain.","section":"The Battle"},{"t":"battle","name":"THE FAITHFUL","firstLines":["You strike first.","He strikes first."],"desc":"**Knee-deep:** a bad swing in water this deep costs you your footing, and your next stroke. It costs him the same.","section":"The Battle"},{"t":"say","text":"Those still on their feet do not stand, as they stood under the Kiln. They break for the far door and the lake beyond it.","section":"The Battle"},{"t":"say","text":"The boy on the table is alive. Joss. The cut on his palm is still bleeding through its linen. In his good hand he holds a little wooden boat, no longer than a finger, and he does not let go of it even while you lift him down.\n\nA chain runs from his ankle to a ring in the drowned floor. The lock on it is older than he is, and mostly rust. It breaks under the flat of a blade.\n\nBehind him, the socket.\n\nEmpty — and this time the dust at its rim hasn''t settled. It''s still falling, a faint grey haze drifting down through the lamplight.","section":"The Battle"},{"t":"section","title":"The United Effort","section":"The United Effort"},{"t":"say","text":"From the far door comes a sound like a bell dropped down a well.\n\nIt is the old water-gate: an iron grille as wide as the doorway, hung up out of the way on a rope for longer than anyone has been alive. The last of them cut that rope as he went under it, so that nobody could follow.\n\nHe was not quite fast enough.\n\nHe is on his back in the doorway with the gate across his legs, in water that would cover him if he lay flat. He is holding himself up on his elbows. His chin is just clear.\n\nBeyond the bars, on the black water: oars, pulling hard, going away. A second boat, the twin of the one you came in, with the same black circle painted on its prow. Then only the sound of it.\n\nHe does not call after them.","section":"The United Effort"},{"t":"say","text":"You have known since the Kiln what his kind are. *The faithful shall not lie.* He is the only one left who can answer you.","section":"The United Effort"},{"t":"say","text":"The gate cannot be lifted. It came down crooked, and one corner has jammed in the groove it runs in. Heave at it, and the other corner grinds down on him.\n\nWhat holds it is a single iron pin, low in the groove, under the water. Work the pin out, and the gate will come up like a lid.\n\nThere is room at it for one pair of hands, and for as long as one breath lasts.","section":"The United Effort"},{"t":"ue","section":"The United Effort"},{"t":"say","text":"Two of you take his shoulders. Somebody finds a knife with a good point.","section":"The United Effort"},{"t":"say","text":"You get his shoulders across your knees. One hand for him, one for the knife. One breath.","cond":{"on":"alone"},"section":"The United Effort"},{"t":"ueEnd","won":true,"section":"The United Effort"},{"t":"say","text":"For a moment nothing moves.\n\nThen every one of you has a hand on the bars, and the gate comes up out of its groove with a groan, and he is dragged clear by the collar, coughing black water.\n\nHe does not thank you.\n\nTied at his belt, sealed in a waxed pouch: pages. More of the Order''s scripture, from a book you have not seen before.","cond":{"on":"ue","won":true},"section":"The United Effort"},{"t":"ueEnd","won":false,"section":"The United Effort"},{"t":"say","text":"You get the pin out in the end. It takes all of you, and it takes too long.\n\nWhen the gate comes up, he comes with it like a sack.\n\nHe is breathing. That is all. Whatever he could have told you, he will not tell it tonight.\n\nTied at his belt, sealed in a waxed pouch: pages. More of the Order''s scripture, from a book you have not seen before.","cond":{"on":"ue","won":false},"section":"The United Effort"},{"t":"section","title":"Notice","section":"Notice"},{"t":"notice","lines":{"Might":"Under the Kiln they stood their ground to the last man. Tonight they ran the moment they could.","Agility":"The water in the far doorway is still rocking. Whoever went out, went out as you came in.","Intellect":"The linen on his hand is soaked through. This cut is not an hour old.","Charm":"Joss has not let go of the little boat. He is listening to the oars, and he knows the sound.","Craft":"The dust is falling from inside the socket. Whatever sat there was lifted out, with care, not knocked loose.","Aim":"In the other boat, the one going away, with a circle on its prow like the one on yours: four at the oars, and a fifth in the stern who is not rowing. He is holding something in both arms.","floor":"Lying in the water you can see along its surface to the door. Something small is floating there: a curl of whittled wood."},"section":"Notice"},{"t":"act","label":"LOOK CLOSER","section":"Notice"},{"t":"lookCloser","lines":{"Might":"And the one you fought kept his back to the wall the whole time. He was not guarding the boy.","Agility":"A wet handprint on the door jamb. One hand. The other was full.","Intellect":"They have never before left a child still bleeding. They did not have the time.","Charm":"He has heard it every night since they took him.","Craft":"The inside is worn as smooth as a bowl. It held the same thing for a very long time.","Aim":"Not a child. It is far too small."},"section":"Notice"},{"t":"section","title":"Ask","section":"Ask"},{"cond":{"on":"ue","won":true},"t":"say","text":"He is on his knees in the water, still coughing.\n\n**You may ask him.** Each of you, one question, whenever you choose. The board stays up for the rest of the night, and new questions will come as things are found.","section":"Ask"},{"cond":{"on":"ue","won":true},"t":"ask","rows":[{"questions":["WHAT GOES IN THERE?"],"sealed":true,"note":"","answer":"He doesn''t answer. He flinches — the whole of him, like a struck animal — and looks anywhere but the socket.","group":"Tonight turns on this"},{"questions":["WHO LEADS YOU?"],"sealed":false,"note":"","answer":"*\"One whose face I''ve never seen.\"*","group":"The faithful"},{"questions":["IS HE HERE?"],"sealed":false,"note":"","answer":"*\"I don''t know. I''ve never seen his face.\"*","group":"The faithful"},{"questions":["DO YOU KNOW THIS MAN?"],"sealed":false,"note":"of Garrick","answer":"*\"No.\"*","group":"The faithful"},{"questions":["THE OTHERS YOU TOOK, BEFORE"],"sealed":false,"note":"","answer":"*\"Most went home.\"* Pressed on the charcoal woman''s nephew: *\"Him we lost.\"* *\"Not by our choosing.\"*","group":"The faithful"},{"questions":["WHOSE IS THIS?"],"sealed":false,"note":"","answer":"*\"The scholar''s.\"*","group":"Added when the pen is found"},{"questions":["IS SHE DEAD?"],"sealed":false,"note":"","answer":"*\"Yes.\"*","group":"Added when the pen is found"},{"questions":["DID YOUR PEOPLE KILL HER?"],"sealed":false,"note":"","answer":"*\"Yes.\"* Asked why: silence.","group":"Added when the pen is found"},{"questions":["DID YOU KILL HER?"],"sealed":false,"note":"","answer":"*\"No.\"*","group":"Added when the pen is found"},{"questions":["WHERE DID YOU GET IT?"],"sealed":false,"note":"","answer":"*\"With her pages.\"*","group":"Added when the pen is found"},{"questions":["HOW DOES THE PAGE END?"],"sealed":false,"note":"","answer":"*\"I have never seen it whole.\"*","group":"Added when the torn page is read"},{"questions":["WILL THE FIFTH STOP HIM?"],"sealed":false,"note":"","answer":"Silence.","group":"Added when the torn page is read"},{"questions":["WHO GAVE YOU THIS PAGE?"],"sealed":false,"note":"","answer":"*\"It was given me to carry.\"*","group":"Added when the torn page is read"}],"section":"Ask","unaskedLine":"Nobody asks it. Somebody only looks from him to the socket, and that is enough. He flinches — the whole of him, like a struck animal — and looks anywhere else."},{"t":"section","title":"The Verse of the Four","section":"The Verse of the Four"},{"t":"say","text":"*From the Second Book of the Order of the Dark Moon — The Verse of the Four.*\n\n*Hear what the moon left behind.*\n\n*Before there were kings, the moon broke. No telling survives of why. What fell from it fell everywhere — into the hills, into the deep water, into the dark beneath the roots of the world — and where each piece came to rest, it kept a little of the moon inside it, the way a coal keeps a little of the fire.*\n\n*So too the children born in the hour when the moon goes dark. The same light marks them. Their blood remembers what the shards remember. Set that blood upon a shard, and the shard remembers too — and wakes.*","section":"The Verse of the Four"},{"t":"match","question":"WHICH OF YOUR FRAGMENTS IS THIS?","quote":"*\"Their blood remembers what the shards remember.\"*","source":"From the housing at the drowned tower","section":"The Verse of the Four","answer":"4-3"},{"t":"act","label":"READ ON","section":"The Verse of the Four"},{"t":"say","text":"*For longer than any of us can count, the faithful gave the marked blood in his name, and he slept on. Blood poured out upon the ground is only blood. It must be given to a shard.*\n\n*When the Seekers had struck down their king, they took the shards that had served them and carried them to the far places of the land, and hid them, and set their own blood as the lock upon every way that led to them. Nothing of theirs, they said, would ever be found by any hand but their children''s.*\n\n*They were right.*\n\n*Therefore the faithful have not waited for the ways to open. We have waited for those who can open them. Where the Seekers'' children walk, the faithful follow, closer to them than their own shadows. Where a shard is uncovered, a marked child is brought to it, and the shard drinks, and wakes, and is carried home to him.*\n\n*One shard that has drunk is a coal in the dark, and no more. But when four have drunk, the sleep that holds him wears thin as ice in spring — and as each is carried home and set about him, it thins the faster, until the sky itself remembers the night he answered.*\n\n*Until the throne rise whole.*","section":"The Verse of the Four"},{"t":"section","title":"The turn","section":"The turn"},{"t":"say","text":"Under the Kiln: a robed figure going up the vent, a small box clutched to his chest.","section":"The turn"},{"t":"say","text":"On the north road, the carter: four armed riders, and one closed box between them, *\"no bigger than a bread crock\"*.","section":"The turn"},{"t":"say","text":"Tonight, past that doorway: a second boat, like yours, with the same black circle on its prow, and oars going away.","section":"The turn"},{"t":"say","text":"And from the page you have just read: *Where the Seekers'' children walk, the faithful follow.*","section":"The turn"},{"t":"turn","question":"*Every socket was empty. Where did they go?*","section":"The turn","nudge":"*Count the boxes.*","answer":"Carried home to him. Every one, through a door that only your blood could open."},{"t":"say","text":"**This was never about you.**","alone":true,"section":"The turn"},{"t":"section","title":"Garrick","section":"Garrick"},{"t":"say","text":"Garrick has read the page over your shoulder. His voice is low and steady. *\"It''s the Stones that wake him. Malakor.\"*\n\nA name scraped off every stone in the world, and he says it like a man who has always known it.","section":"Garrick"},{"t":"act","label":"HOW DO YOU KNOW THAT NAME?","section":"Garrick"},{"t":"say","text":"He doesn''t look up from the page. *\"My grandmother taught me that name.\"*","section":"Garrick"},{"t":"say","text":"*\"Four Stones. Four children,\"* he says. *\"That''s the shape of what''s written here.\"*","section":"Garrick"},{"t":"act","label":"IS HE AWAKE?","section":"Garrick"},{"t":"say","text":"*\"Everything on this page says the sleep wears thin. Thin.\"*","section":"Garrick"},{"t":"act","label":"CAN IT STILL BE STOPPED?","section":"Garrick"},{"t":"say","text":"He looks at the page a long moment. *\"I won''t promise you that.\"*","section":"Garrick"},{"t":"section","title":"The pen","section":"The pen"},{"t":"say","text":"There is one more thing in the pouch, under the pages: a pen. Plain brass, the nib stained with the same brown ink as every page of Meira''s notes. Scratched small into the barrel, in her neat hand, are her initials.\n\nNobody says anything for a while.\n\nHer satchel is opened, the way you would open the door of an empty room. Her hand is on every page. Every trail you have followed since the forest road, she walked first. And somewhere on a road, someone took this pen out of her hand, and she did not come back for it.\n\nThe pen goes into the satchel, with the rest of her.","section":"The pen"},{"t":"section","title":"The torn page","section":"The torn page"},{"t":"say","text":"Under where the pen lay, one last page, burned black along one edge, the rest of it torn clean through. The top lines are in the Order''s hand. The rest is set apart, in the older hand you first saw in the Order''s scripture under the mill hill: the hand the Order itself calls older than its name.","section":"The torn page"},{"t":"say","text":"*From the Second Book of the Order of the Dark Moon. Even in the old telling, before we had our name, it was known—*\n\n*Here the hand changes. The rest is set apart, in the older hand:*\n\n**\"Four were given to the wind, the water, the fire, and the earth, and drink deep whichever marked blood finds them first. The fifth heeds no element at all, but blood alone, and remembers whose. What the four begin, the fifth shall end—\"**\n\nThe page is torn there, its edge burned black. Whatever came next is gone.","section":"The torn page"},{"t":"match","question":"WHICH OF YOUR FRAGMENTS IS THIS?","quote":"*\"The fifth heeds no element at all…\"*","source":"From the old ford, on the north road","section":"The torn page","answer":"4-2"},{"t":"say","text":"Two hands, centuries apart.","section":"The torn page"},{"t":"say","text":"Garrick says it quietly, like a man setting down something heavy. *\"There''s one more. A fifth Stone — she wrote about it.\"*\n\nAnd she did. Her footnote from the Blackglass, the one she wrote off: *\"Five, the fragment says... A poet''s count, perhaps.\"*","section":"The torn page"},{"t":"say","text":"*What the four begin, the fifth shall end—*","alone":true,"section":"The torn page"},{"t":"say","text":"Garrick says nothing at all.","section":"The torn page"},{"t":"section","title":"The Cliffhanger","section":"The Cliffhanger"},{"t":"say","text":"You come up out of the undercroft into the open boat, Joss wrapped in someone''s coat in the bow, the little boat still in his fist. It has been a long night, and it is nearly over: in the east, over the far shore of the Stillwater, the sky has begun to pale.\n\nThen it stops.\n\nThe light does not grow. It goes grey and flat and hangs there, thin, as though something vast has leaned across the sun before it could rise. Along the shore, the birds that should be starting up stay silent, row by row.\n\n*Until the sky itself remembers the night he answered.*\n\nAnd from somewhere far to the north, so deep you feel it in your teeth more than hear it, comes a single sound. Slow. Enormous. Like a heartbeat.\n\nThen another.","section":"The Cliffhanger"},{"t":"summary","lines":["**THE DROWNED UNDERCROFT** · Gathering 4","{EARNED}","The party: Battle {battle} · the water-gate: {ue:he lived to answer, {asked} questions asked|he did not wake}","You learned: **the children''s blood wakes the Stones, and the Stones wake him.** Every socket held one. The Order followed you to each door, and carried each Stone home to him. Joss is alive. Meira is not: they had her pen. And there is a fifth Stone, on a page torn off at *the fifth shall end—*","Tomorrow: **a dawn that stopped halfway**"],"section":"The Cliffhanger"}],"ue":{"success":{"0":["It comes out in your hand."],"1":["The pin is half out and loose as a bad tooth. You work it until your ears are singing, and come up with the taste of iron in your mouth.","It moves under your thumb. One more like that."],"2":["It is turning now. Each twist brings a thread of rust up past your face like smoke. You feel it shift in its hole before your breath gives out.","A quarter-turn. Another. The gate above you makes a small, different sound."],"3":["Your fingers find it in the dark: a pin of iron as thick as a thumb, furred with rust. You get the knife''s point under its head and lean. Something gives, a grain at a time. Then your chest is burning, and you are up.","You have it at once this time. The point finds the lip of the pin''s head, and you feel the rust break like a crust."]},"fail":{"0":["The gate settles one last time. He goes under, and he is very quiet under their hands."],"1":["The knife slips. The gate drops again, and this time he does not struggle when he goes under. When they lift him his lips are blue, and his eyes do not find anyone.","The gate grinds. The two holding his shoulders have to go under with him to keep hold."],"2":["The gate grinds down. He is under for a slow count of five before they get his face clear.","The gate takes a weight it did not have before, and gives. He has stopped holding himself up. They are doing it for him now."],"3":["The point skates off the rust and rings on the bars. The gate shudders, and settles the width of a finger. It is enough. His elbows go from under him, and the water closes over his face. They haul him up. He comes up coughing.","You come up under the wrong bar, and the whole gate rings. He goes under; comes up; spits; says nothing."]},"between":["Out on the lake the oars are fainter. Whatever they carried out of here, it is not coming back.","From the table, Joss is watching. He has the little boat held so tight that his knuckles are white.","The man under the gate has not once asked you to hurry."]}}'::jsonb)
on conflict (series_id, season_number, week) do update set data = excluded.data;
